/**
 * =============================================================================
 * BLOCKCHAIN CARD — Staged confirmation animation
 * =============================================================================
 * Visualises the blockchain anchoring process as a 4-5 second sequence:
 *   Stage 1 (0-1.5s): Submitting — progress bar to 33%
 *   Stage 2 (1.5-3s): Pending   — progress bar to 66%
 *   Stage 3 (3-4.5s): Confirmed — progress bar to 100%, reveal tx details
 *
 * The animation is designed for live demos: the presenter narrates each stage.
 * Set animate={false} to show the confirmed state immediately.
 * =============================================================================
 */

import { useEffect, useRef, useState } from 'react';
import { useAnimate, motion } from 'motion/react';
import { Copy, Check } from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import type { ConfirmationStage, BlockchainProof } from './types';

// =============================================================================
// STAGE CONFIG
// =============================================================================

const STAGES: { key: ConfirmationStage; label: string }[] = [
  { key: 'submitting', label: 'Submitting' },
  { key: 'pending', label: 'Pending' },
  { key: 'confirmed', label: 'Confirmed' },
];

// =============================================================================
// COMPONENT
// =============================================================================

interface BlockchainCardProps {
  proof: BlockchainProof;
  animate?: boolean;
}

export function BlockchainCard({ proof, animate = true }: BlockchainCardProps) {
  const [scope, animateFn] = useAnimate();
  const [stage, setStage] = useState<ConfirmationStage>(animate ? 'idle' : 'confirmed');
  const [copied, setCopied] = useState(false);
  const hasAnimated = useRef(false);

  // Run the staged animation sequence
  useEffect(() => {
    if (!animate || hasAnimated.current) return;
    hasAnimated.current = true;

    const runSequence = async () => {
      // Stage 1: Submitting (0-1.5s)
      setStage('submitting');
      await animateFn(
        '[data-progress-bar]',
        { width: '33%' },
        { duration: 1.2, ease: 'easeOut' },
      );
      await new Promise((r) => setTimeout(r, 300));

      // Stage 2: Pending (1.5-3s)
      setStage('pending');
      await animateFn(
        '[data-progress-bar]',
        { width: '66%' },
        { duration: 1.2, ease: 'easeOut' },
      );
      await new Promise((r) => setTimeout(r, 300));

      // Stage 3: Confirmed (3-4.5s)
      setStage('confirmed');
      await animateFn(
        '[data-progress-bar]',
        { width: '100%' },
        { duration: 0.8, ease: 'easeOut' },
      );

      // Checkmark flourish
      try {
        await animateFn(
          '[data-confirmed-icon]',
          { scale: [0.8, 1.05, 1] },
          { duration: 0.4 },
        );
      } catch {
        // Element may not be mounted yet
      }
    };

    runSequence();
  }, [animate, animateFn]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(proof.txHash);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Clipboard not available
    }
  };

  const truncateHash = (hash: string) =>
    `${hash.slice(0, 8)}...${hash.slice(-8)}`;

  const networkLabel = proof.network || 'devnet';

  return (
    <Card
      className="border-primary/20 bg-card overflow-hidden"
      data-testid="blockchain-card"
    >
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base">Blockchain Anchoring</CardTitle>
          <Badge variant="outline" className="text-[10px] uppercase tracking-wider">
            {networkLabel}
          </Badge>
        </div>
      </CardHeader>

      <CardContent ref={scope}>
        {/* Progress bar */}
        <div className="h-1 bg-muted rounded-full overflow-hidden mb-4">
          <div
            data-progress-bar
            className="h-full bg-primary rounded-full"
            style={{ width: stage === 'confirmed' && !animate ? '100%' : '0%' }}
          />
        </div>

        {/* Stage indicators */}
        <div className="flex justify-between mb-4" data-testid="stage-indicators">
          {STAGES.map((s, idx) => {
            const stageIdx = STAGES.findIndex((st) => st.key === stage);
            const isActive = s.key === stage;
            const isPast = idx < stageIdx;

            return (
              <div
                key={s.key}
                className={cn(
                  'text-xs transition-colors duration-300',
                  isActive && s.key === 'confirmed'
                    ? 'text-primary font-semibold'
                    : isActive
                      ? 'text-primary'
                      : isPast
                        ? 'text-muted-foreground'
                        : 'text-muted-foreground/50',
                )}
                data-testid={`stage-${s.key}`}
              >
                {s.key === 'confirmed' && isActive && (
                  <span data-confirmed-icon className="inline-block mr-1">
                    <Check className="w-3.5 h-3.5 inline -mt-0.5" />
                  </span>
                )}
                {s.label}
              </div>
            );
          })}
        </div>

        {/* Tx details — revealed on confirmation */}
        {stage === 'confirmed' && (
          <motion.div
            initial={animate ? { opacity: 0, y: 8 } : false}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, delay: 0.1 }}
            className="space-y-2 pt-2 border-t border-border"
            data-testid="tx-details"
          >
            <div className="flex items-center justify-between text-xs">
              <span className="text-muted-foreground">Tx Hash</span>
              <button
                onClick={handleCopy}
                className="flex items-center gap-1.5 font-mono text-[11px] text-primary hover:text-primary/80 transition-colors"
                data-testid="copy-tx-hash"
              >
                {truncateHash(proof.txHash)}
                {copied ? (
                  <Check className="w-3 h-3 text-green-500" />
                ) : (
                  <Copy className="w-3 h-3" />
                )}
              </button>
            </div>

            <div className="flex items-center justify-between text-xs">
              <span className="text-muted-foreground">Block</span>
              <span className="font-mono text-[11px]" data-testid="block-number">
                {proof.blockNumber.toLocaleString()}
              </span>
            </div>

            {proof.slot !== undefined && (
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">Slot</span>
                <span className="font-mono text-[11px]">
                  {proof.slot.toLocaleString()}
                </span>
              </div>
            )}

            {proof.confirmedAt && (
              <div className="flex items-center justify-between text-xs">
                <span className="text-muted-foreground">Confirmed</span>
                <span className="text-[11px]">
                  {new Date(proof.confirmedAt).toLocaleString()}
                </span>
              </div>
            )}
          </motion.div>
        )}
      </CardContent>
    </Card>
  );
}

export default BlockchainCard;

